#include "opt.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

void optimize_bytecode(Bytecode *bc) {
    if (!bc || bc->count == 0) return;

    // NOTE: The SSA MIR pass (ssa_build_from_bytecode + GVN/DCE/regalloc) was
    // removed here because its results were never written back to `bc` — it
    // built and freed an SSAFunc per compiled function with zero effect on the
    // generated bytecode, i.e. pure compile-time allocator churn. The ssa.c
    // routines remain available for a future pass that actually consumes them.

    // Pass 1: Identify all jump targets to define basic block boundaries
    signed char *is_jump_target = calloc(bc->count, sizeof(signed char));
    for (int i = 0; i < bc->count; i++) {
        Instruction *inst = &bc->code[i];
        if (inst->op == OP_JUMP || inst->op == OP_JUMP_IF_FALSE || inst->op == OP_JUMP_IF_TRUE) {
            if (inst->arg >= 0 && inst->arg < bc->count) {
                is_jump_target[inst->arg] = 1;
            }
        }
    }

    // Determine the number of registers actually used so the per-register
    // tracking tables are sized dynamically instead of being hard-capped at
    // 1024 (which silently disabled optimization for programs using more
    // registers than that).
    int max_reg = -1;
    for (int i = 0; i < bc->count; i++) {
        Instruction *inst = &bc->code[i];
        if (inst->r0 >= 0 && inst->r0 > max_reg) max_reg = inst->r0;
        if (inst->r1 >= 0 && inst->r1 > max_reg) max_reg = inst->r1;
        if (inst->r2 >= 0 && inst->r2 > max_reg) max_reg = inst->r2;
    }
    int nregs = max_reg + 1;
    if (nregs < 0) nregs = 0;

    Value *const_vals = nregs ? calloc(nregs, sizeof(Value)) : NULL;
    signed char *is_const = nregs ? calloc(nregs, sizeof(signed char)) : NULL;
    unsigned char *reg_types = nregs ? calloc(nregs, sizeof(unsigned char)) : NULL; // 0=Unknown, 1=Int, 2=Float, 3=String, 4=Bool

    // Pass 2: Type Inference and Constant Folding (Multi-pass dataflow propagation)
    for (int pass = 0; pass < 3; pass++) {
    for (int i=0; i < bc->count; i++) {
        Instruction *inst = &bc->code[i];

        // If this instruction is a jump target, it starts a new basic block.
        // We invalidate constant tracking because jump sources may differ,
        // but preserve inferred variable types across loop boundaries.
        if (is_jump_target[i]) {
            memset(is_const, 0, nregs * sizeof(*is_const));
        }

        if (inst->op == OP_CONST_INT) {
            if (inst->r0 < nregs) {
                is_const[inst->r0] = 1;
                const_vals[inst->r0] = value_int(inst->arg);
                reg_types[inst->r0] = 1;
            }
            inst->type = 1;
        }
        else if (inst->op == OP_CONST_FLOAT) {
            if (inst->r0 < nregs) {
                reg_types[inst->r0] = 2;
            }
            inst->type = 2;
        }
        else if (inst->op == OP_CONST_STRING) {
            if (inst->r0 < nregs) {
                reg_types[inst->r0] = 3;
            }
            inst->type = 3;
        }
        else if (inst->op == OP_CONST_BOOL) {
            if (inst->r0 < nregs) {
                is_const[inst->r0] = 1;
                const_vals[inst->r0] = value_bool(inst->arg);
                reg_types[inst->r0] = 4;
            }
            inst->type = 4;
        }
        else if (inst->op == OP_ADD || inst->op == OP_SUB || inst->op == OP_MUL || inst->op == OP_DIV) {
            int r0 = inst->r0;
            int r1 = inst->r1;
            int r2 = inst->r2;
            
            if (r1 < nregs && r2 < nregs) {
                // Type Inference
                if (reg_types[r1] == 1 && reg_types[r2] == 1) {
                    if (r0 < nregs) reg_types[r0] = 1;
                    inst->type = 1;
                    if (inst->op == OP_ADD) inst->op = OP_ADD_INT;
                    else if (inst->op == OP_SUB) inst->op = OP_SUB_INT;
                    else if (inst->op == OP_MUL) inst->op = OP_MUL_INT;
                } else if (reg_types[r1] == 2 || reg_types[r2] == 2) {
                    if (r0 < nregs) reg_types[r0] = 2;
                    inst->type = 2;
                }
                
                // Constant folding
                if (is_const[r1] && is_const[r2]) {
                    Value v1 = const_vals[r1];
                    Value v2 = const_vals[r2];
                    if (GET_TYPE(v1) == VAL_INT && GET_TYPE(v2) == VAL_INT) {
                        int64_t i1 = AS_INT(v1);
                        int64_t i2 = AS_INT(v2);
                        int64_t res = 0;
                        int ok = 1;
                        if (inst->op == OP_ADD || inst->op == OP_ADD_INT) res = i1 + i2;
                        else if (inst->op == OP_SUB || inst->op == OP_SUB_INT) res = i1 - i2;
                        else if (inst->op == OP_MUL || inst->op == OP_MUL_INT) res = i1 * i2;
                        else if (inst->op == OP_DIV) { if (i2 != 0 && i1 % i2 == 0) res = i1 / i2; else ok = 0; }
                        
                        if (ok && res >= INT32_MIN && res <= INT32_MAX && fits_int48(res)) {
                            inst->op = OP_CONST_INT;
                            inst->arg = (int)res;
                            if (r0 < nregs) {
                                is_const[r0] = 1;
                                const_vals[r0] = value_int(res);
                                reg_types[r0] = 1;
                            }
                            inst->type = 1;
                        }
                    }
                }
            }
        }
        else if (inst->op >= OP_LT && inst->op <= OP_EQ) {
            int r1 = inst->r1;
            int r2 = inst->r2;
            if (r1 < nregs && r2 < nregs) {
                if (reg_types[r1] == 1 && reg_types[r2] == 1) {
                    if (inst->op == OP_LT) inst->op = OP_LT_INT;
                    else if (inst->op == OP_GT) inst->op = OP_GT_INT;
                    else if (inst->op == OP_LTE) inst->op = OP_LTE_INT;
                    else if (inst->op == OP_GTE) inst->op = OP_GTE_INT;
                    else if (inst->op == OP_EQ) inst->op = OP_EQ_INT;
                }
            }
        }
        else if (inst->op == OP_MOVE) {
            if (inst->r1 < nregs && inst->r0 < nregs) {
                is_const[inst->r0] = is_const[inst->r1];
                const_vals[inst->r0] = const_vals[inst->r1];
                reg_types[inst->r0] = reg_types[inst->r1];
                inst->type = reg_types[inst->r1];
            }
        } else {
            if (inst->r0 < nregs) {
                is_const[inst->r0] = 0;
            }
        }
    }
    }

    // Pass 3: Scalar Replacement
    int *virtual_bases = nregs ? calloc(nregs, sizeof(int)) : NULL;
    int *virtual_sizes = nregs ? calloc(nregs, sizeof(int)) : NULL;
    for (int j=0; j<nregs; j++) { virtual_bases[j] = -1; virtual_sizes[j] = 0; }

    for (int i=0; i < bc->count; i++) {
        Instruction *inst = &bc->code[i];

        if (is_jump_target[i]) {
            for (int j=0; j<nregs; j++) { virtual_bases[j] = -1; virtual_sizes[j] = 0; }
        }

        if (inst->op == OP_LIST_LITERAL && inst->is_stack_alloc && inst->arg <= 4) {
            if (inst->r0 < nregs) {
                virtual_bases[inst->r0] = inst->r1;
                virtual_sizes[inst->r0] = inst->arg;
                inst->op = OP_NOP;
            }
        }
        else if (inst->op == OP_INDEX) {
            int coll_reg = inst->r1;
            int idx_reg = inst->r2;
            if (coll_reg < nregs && virtual_bases[coll_reg] != -1) {
                if (idx_reg < nregs && is_const[idx_reg]) {
                    int k = (int)AS_INT(const_vals[idx_reg]);
                    if (k >= 0 && k < virtual_sizes[coll_reg]) {
                        inst->op = OP_MOVE;
                        inst->r1 = virtual_bases[coll_reg] + k;
                    }
                }
            }
        }
        else if (inst->op == OP_LEN) {
             int coll_reg = inst->r1;
             if (coll_reg < nregs && virtual_bases[coll_reg] != -1) {
                 inst->op = OP_CONST_INT;
                 inst->arg = virtual_sizes[coll_reg];
             }
        }
        else if (inst->op == OP_STORE_INDEX) {
            int coll_reg = inst->r0;
            int idx_reg = inst->r1;
            int src_reg = inst->r2;
            if (coll_reg < nregs && virtual_bases[coll_reg] != -1) {
                if (idx_reg < nregs && is_const[idx_reg]) {
                    int k = (int)AS_INT(const_vals[idx_reg]);
                    if (k >= 0 && k < virtual_sizes[coll_reg]) {
                        inst->op = OP_MOVE;
                        inst->r0 = virtual_bases[coll_reg] + k;
                        inst->r1 = src_reg;
                    }
                }
            }
        }
    }
    
    // Pass 4: Loop Auto-Vectorization
    for (int i = 0; i < bc->count - 12; i++) {
        Instruction *lt = &bc->code[i];
        if (lt->op == OP_LTE || lt->op == OP_LT) {
            Instruction *jf = &bc->code[i+1];
            if (jf->op == OP_JUMP_IF_FALSE) {
                int exit_pc = jf->arg;
                // Pattern for res[i] = a[i] + b[i]
                // 4: LOAD_VAR (i) -> r_idx
                // 34: INDEX (a, r_idx) -> r_a
                // 4: LOAD_VAR (i) -> r_idx2
                // 34: INDEX (b, r_idx2) -> r_b
                // 6: ADD (r_a, r_b) -> r_res
                // 36: STORE_INDEX (res, r_idx, r_res)
                
                if (bc->code[i+2].op == OP_LOAD_VAR && 
                    bc->code[i+3].op == OP_INDEX &&
                    bc->code[i+4].op == OP_LOAD_VAR &&
                    bc->code[i+5].op == OP_INDEX &&
                    bc->code[i+6].op == OP_ADD &&
                    bc->code[i+7].op == OP_STORE_INDEX) {
                    
                    // Match!
                    jf->op = OP_SIMD_ADD;
                    jf->r0 = bc->code[i+7].r0; // target collection
                    jf->r1 = bc->code[i+3].r1; // a collection
                    jf->r2 = bc->code[i+5].r1; // b collection
                    
                    // Cleanup loop body
                    for (int k = i+2; k < exit_pc && k < bc->count - 1; k++) {
                        if (bc->code[k].op != OP_JUMP) bc->code[k].op = OP_NOP;
                    }
                }
            }
        }
    }
    // Pass 4.5: Devirtualize CALL_VALUE
    for (int i = 0; i < bc->count - 1; i++) {
        Instruction *load = &bc->code[i];
        Instruction *call = &bc->code[i+1];
        if (load->op == OP_LOAD_VAR && call->op == OP_CALL_VALUE && load->r0 == call->r1) {
            const char *name = global_table.names[load->arg];
            FuncEntry *fe = func_get(name);
            if (fe && fe->body) {
                call->op = OP_CALL;
                call->ptr = (intptr_t)name;
                load->op = OP_NOP;
            }
        }
    }
    
    // Pass 5: Tail Call & Self-Call Fast Optimization (Early Decision)
    for (int i = 0; i < bc->count; i++) {
        Instruction *pc = &bc->code[i];

        if (pc->op == OP_CALL || pc->op == OP_CALL_VALUE || pc->op == OP_CALL_SELF_FAST) {
            // Look ahead for RETURN, skipping NOPs
            int next_idx = i + 1;
            while (next_idx < bc->count && bc->code[next_idx].op == OP_NOP) next_idx++;
            
            if (next_idx < bc->count && bc->code[next_idx].op == OP_RETURN && pc->r0 == bc->code[next_idx].r0) {
                // Only tail-call when the target is a plain function. A class
                // constructor compiles to OP_CALL_VALUE loading the class, and
                // its result is the freshly-built instance, not the callee's
                // return value. The tail path forwards the callee's return, so
                // TCO'ing a constructor drops the instance (`return Foo(x)` then
                // yields a corrupt value). Named funcs and self-calls are safe;
                // a dynamic OP_CALL_VALUE callee (class/lambda/method) is not.
                int tco_safe = 0;
                if (pc->op == OP_CALL_SELF_FAST) {
                    tco_safe = 1;
                } else if (pc->op == OP_CALL && pc->ptr) {
                    FuncEntry *fe = func_get((const char*)pc->ptr);
                    if (fe && fe->body) tco_safe = 1;
                }
                if (tco_safe) {
                    pc->op = OP_TAIL_CALL;
                    bc->code[next_idx].op = OP_NOP;
                    continue;
                }
            }
        }

        // 2. Self-Call Fast Path (if not already TCO'd)
        if (pc->op == OP_CALL) {
             const char *name = (const char*)pc->ptr;
             if (name && bc->owner && bc->owner->name && strcmp(name, bc->owner->name) == 0) {
                 pc->op = OP_CALL_SELF_FAST;
                 
                 // Re-check for TCO after patching to SELF_FAST
                 int next_idx = i + 1;
                 while (next_idx < bc->count && bc->code[next_idx].op == OP_NOP) next_idx++;
                 if (next_idx < bc->count && bc->code[next_idx].op == OP_RETURN && pc->r0 == bc->code[next_idx].r0) {
                     pc->op = OP_TAIL_CALL;
                     bc->code[next_idx].op = OP_NOP;
                 }
             }
        }
        }
    // Pass 6: Method Devirtualization
    for (int i = 0; i < bc->count - 1; i++) {
        Instruction *pc = &bc->code[i];
        if (pc->op == OP_GET_PROPERTY) {
            int next_idx = i + 1;
            while (next_idx < bc->count && bc->code[next_idx].op == OP_NOP) next_idx++;
            if (next_idx < bc->count && bc->code[next_idx].op == OP_CALL_VALUE) {
                Instruction *call_pc = &bc->code[next_idx];
                if (pc->r0 == call_pc->r1) {
                    call_pc->op = OP_CALL_METHOD;
                    call_pc->ptr = pc->ptr; // name of method
                    // r1 of OP_CALL_METHOD needs the object
                    call_pc->r1 = pc->r1;
                    
                    // We can eliminate OP_GET_PROPERTY
                    pc->op = OP_NOP;
                }
            }
        }
    }

    // Pass 7: Peephole Copy Propagation / Temporary Elimination for Binary Ops
    for (int iter = 0; iter < 3; iter++) {
    for (int i = 0; i < bc->count; i++) {
        Instruction *pc = &bc->code[i];
        int is_bin = (pc->op >= OP_ADD && pc->op <= OP_NEQ) || 
                     (pc->op >= OP_ADD_INT && pc->op <= OP_EQ_INT);
        if (!is_bin) continue;

        // Backward scan for r1 temporary move
        int b1 = i - 1;
        while (b1 >= 0 && bc->code[b1].op == OP_NOP && !is_jump_target[b1+1]) b1--;
        if (b1 >= 0 && !is_jump_target[b1+1] && bc->code[b1].op == OP_MOVE && bc->code[b1].r0 == pc->r1) {
            int target_reg = bc->code[b1].r0;
            pc->r1 = bc->code[b1].r1;
            // Only NOP the move if target_reg is not read anywhere else
            int is_read_elsewhere = 0;
            for (int k = 0; k < bc->count; k++) {
                if (k == b1 || k == i) continue;
                Instruction *inst = &bc->code[k];
                if (inst->op == OP_NOP) continue;
                if (inst->r1 == target_reg || inst->r2 == target_reg) { is_read_elsewhere = 1; break; }
            }
            if (!is_read_elsewhere) bc->code[b1].op = OP_NOP;
        }

        // Backward scan for r2 temporary move
        int b2 = i - 1;
        while (b2 >= 0 && bc->code[b2].op == OP_NOP && !is_jump_target[b2+1]) b2--;
        if (b2 >= 0 && !is_jump_target[b2+1] && bc->code[b2].op == OP_MOVE && bc->code[b2].r0 == pc->r2) {
            int target_reg = bc->code[b2].r0;
            pc->r2 = bc->code[b2].r1;
            // Only NOP the move if target_reg is not read anywhere else
            int is_read_elsewhere = 0;
            for (int k = 0; k < bc->count; k++) {
                if (k == b2 || k == i) continue;
                Instruction *inst = &bc->code[k];
                if (inst->op == OP_NOP) continue;
                if (inst->r1 == target_reg || inst->r2 == target_reg) { is_read_elsewhere = 1; break; }
            }
            if (!is_read_elsewhere) bc->code[b2].op = OP_NOP;
        }

        /* Forward scan output move disabled */
    }
    }

    free(virtual_bases);
    free(virtual_sizes);
    free(const_vals);
    free(is_const);
    free(reg_types);
    free(is_jump_target);
}
